using TMPro;
using UnityEngine;

namespace ZooThrow.UI
{
    /// <summary>
    /// Cyrillic fonts: Russo One for headings, PT Sans Bold for body text (both SIL OFL, in Assets/ZooThrow/Fonts).
    /// The TMP font assets are generated by the editor setup into Resources/Fonts. If they are missing, TMP's default
    /// font is used so the game still runs (Cyrillic then depends on that font's fallbacks).
    /// </summary>
    public static class FontLibrary
    {
        public const string TitlePath = "Fonts/RussoOne SDF";
        public const string BodyPath = "Fonts/PTSans SDF";

        public static TMP_FontAsset Title { get; private set; }
        public static TMP_FontAsset Body { get; private set; }
        public static Material TitleOutline { get; private set; }
        public static Material BodyOutline { get; private set; }
        public static bool UsingFallback { get; private set; }

        public static void Init()
        {
            Title = Resources.Load<TMP_FontAsset>(TitlePath);
            Body = Resources.Load<TMP_FontAsset>(BodyPath);
            var fallback = TMP_Settings.defaultFontAsset;
            UsingFallback = Title == null || Body == null;
            if (Body == null) Body = Title != null ? Title : fallback;
            if (Title == null) Title = Body;
            if (Title == null)
            {
                Debug.LogError("[ZooThrow] Нет ни одного TMP-шрифта. Запусти меню ZooThrow → Настроить проект (импортирует TMP Essentials и создаст шрифты).");
                return;
            }
            if (UsingFallback) Debug.LogWarning("[ZooThrow] Шрифты ZooThrow не найдены в Resources/Fonts — используется шрифт TMP по умолчанию.");
            TitleOutline = MakeOutline(Title, 0.22f, new Color(0.08f, 0.1f, 0.22f, 1f));
            BodyOutline = MakeOutline(Body, 0.18f, new Color(0.08f, 0.1f, 0.22f, 1f));
        }

        static Material MakeOutline(TMP_FontAsset font, float width, Color color)
        {
            if (font == null || font.material == null) return null;
            var m = new Material(font.material) { name = font.name + " Outline" };
            if (m.HasProperty(ShaderUtilities.ID_OutlineWidth)) m.SetFloat(ShaderUtilities.ID_OutlineWidth, width);
            if (m.HasProperty(ShaderUtilities.ID_OutlineColor)) m.SetColor(ShaderUtilities.ID_OutlineColor, color);
            if (m.HasProperty(ShaderUtilities.ID_FaceDilate)) m.SetFloat(ShaderUtilities.ID_FaceDilate, width * 0.5f);
            if (m.HasProperty(ShaderUtilities.ID_UnderlayColor))
            {
                m.EnableKeyword(ShaderUtilities.Keyword_Underlay);
                m.SetColor(ShaderUtilities.ID_UnderlayColor, new Color(0f, 0f, 0f, 0.45f));
                m.SetFloat(ShaderUtilities.ID_UnderlayOffsetY, -0.8f);
                m.SetFloat(ShaderUtilities.ID_UnderlaySoftness, 0.2f);
            }
            return m;
        }
    }
}
